#pragma oncetemplate< size_t _S >void GuidToString(GUID guid, char (&szGuid)[_S]){  _snprintf_s( szGuid, _S-1,            "{%08X-%04X-%04X-%02X%02X-%02X%02X%02X%02X%02X%02X}",            guid.Data1, guid.Data2, guid.Data3,            guid.Data4[0], guid.Data4[1], guid.Data4[2], guid.Data4[3],            guid.Data4[4], guid.Data4[5], guid.Data4[6], guid.Data4[7]);}inline GUID StringToGuid( LPCSTR pszGuid ){  GUID guid = {};  if( '{'==*pszGuid )    ++pszGuid;  unsigned long p0=0;  int p1=0, p2=2, p3=0, p4=0, p5=0, p6=0, p7=0, p8=0, p9=0, p10=0;    int err = sscanf_s(pszGuid, "%08lX-%04X-%04X-%02X%02X-%02X%02X%02X%02X%02X%02X",                              &p0, &p1, &p2, &p3, &p4, &p5, &p6, &p7, &p8, &p9, &p10);  if( 11!=err )    return guid;  guid.Data1 = p0;  guid.Data2 = p1;  guid.Data3 = p2;  guid.Data4[0] = p3;  guid.Data4[1] = p4;  guid.Data4[2] = p5;  guid.Data4[3] = p6;  guid.Data4[4] = p7;  guid.Data4[5] = p8;  guid.Data4[6] = p9;  guid.Data4[7] = p10;  return guid;}